
const WINDOWS_DEFAULT_WALLPAPER = "data:image/webp;base64,";
const WINDOWS_KEY = "virtual_windows_desktop_v1";
const WINDOWS_DEFAULT = {wallpaper:WINDOWS_DEFAULT_WALLPAPER,apps:[]};
let windowsState;
try{windowsState=JSON.parse(localStorage.getItem(WINDOWS_KEY)||"null")||JSON.parse(JSON.stringify(WINDOWS_DEFAULT));}catch(e){windowsState=JSON.parse(JSON.stringify(WINDOWS_DEFAULT));}
function windowsSave(){try{localStorage.setItem(WINDOWS_KEY,JSON.stringify(windowsState));}catch(e){}}
function windowsEsc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));}
function windowsRender(){
 const c=document.getElementById("windowsCanvas"); if(!c)return;
 c.style.backgroundImage='url("'+(windowsState.wallpaper||WINDOWS_DEFAULT_WALLPAPER)+'")'; c.innerHTML="";
 windowsState.apps.forEach((a,i)=>{
  const e=document.createElement("div"); e.className="windows-icon";
  e.style.left=(a.x??5)+"%"; e.style.top=(a.y??5)+"%"; e.style.width=(a.width??8)+"%";
  e.innerHTML='<img src="'+a.src+'" alt="" style="width:'+Number(a.size||64)+'px;height:'+Number(a.size||64)+'px"><span class="windows-icon-name">'+windowsEsc(a.name||"앱")+"</span>";
  c.appendChild(e);
 });
}
function windowsEditors(){
 const box=document.getElementById("windowsAppList"); if(!box)return; box.innerHTML="";
 windowsState.apps.forEach((a,i)=>{
  const card=document.createElement("div"); card.className="windows-app-card";
  card.innerHTML='<div class="windows-app-top"><span class="windows-app-title">앱 '+(i+1)+'</span><button type="button" class="windows-remove" data-i="'+i+'">삭제</button></div>'+
  '<div class="field"><label>앱 아이콘</label><input class="windows-file" type="file" accept="image/*" data-i="'+i+'" data-kind="icon"></div>'+
  '<div class="field"><label>앱 이름</label><input type="text" value="'+windowsEsc(a.name||"")+'" data-i="'+i+'" data-kind="name" placeholder="예: Chrome"></div>'+
  '<div class="row"><div class="field"><label>위치 X (%)</label><input type="number" min="0" max="93" step="0.5" value="'+(a.x??5)+'" data-i="'+i+'" data-kind="x"></div>'+
  '<div class="field"><label>위치 Y (%)</label><input type="number" min="0" max="88" step="0.5" value="'+(a.y??5)+'" data-i="'+i+'" data-kind="y"></div></div>'+
  '<div class="field"><label>아이콘 크기 (px)</label><input type="number" min="24" max="128" step="1" value="'+(a.size??64)+'" data-i="'+i+'" data-kind="size"></div>';
  box.appendChild(card);
 });
 box.querySelectorAll("[data-kind]").forEach(inp=>{
  inp.addEventListener("input",e=>{const i=+e.target.dataset.i,k=e.target.dataset.kind;if(k==="icon")return;windowsState.apps[i][k]=k==="name"?e.target.value:Number(e.target.value);windowsSave();windowsRender();});
  inp.addEventListener("change",e=>{const i=+e.target.dataset.i,k=e.target.dataset.kind;if(k!=="icon")return;const f=e.target.files&&e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{windowsState.apps[i].src=r.result;windowsSave();windowsRender();};r.readAsDataURL(f);});
 });
 box.querySelectorAll(".windows-remove").forEach(b=>b.addEventListener("click",()=>{windowsState.apps.splice(+b.dataset.i,1);windowsSave();windowsEditors();windowsRender();}));
}
document.getElementById("windowsWallpaper")?.addEventListener("change",e=>{const f=e.target.files&&e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{windowsState.wallpaper=r.result;windowsSave();windowsRender();};r.readAsDataURL(f);});
document.getElementById("windowsAddApp")?.addEventListener("click",()=>{
 const n=windowsState.apps.length;
 windowsState.apps.push({name:"앱",src:"data:image/svg+xml;charset=UTF-8,"+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64"><rect width="64" height="64" rx="10" fill="#ddd"/><text x="32" y="38" text-anchor="middle" font-size="12" fill="#666">APP</text></svg>'),x:5+(n%4)*9,y:5+Math.floor(n/4)*13,size:64,width:8});
 windowsSave();windowsEditors();windowsRender();
});
document.getElementById("windowsReset")?.addEventListener("click",()=>{windowsState=JSON.parse(JSON.stringify(WINDOWS_DEFAULT));windowsSave();windowsEditors();windowsRender();});
windowsEditors();windowsRender();
